-- RUNNING BASE #2-4
UPDATE program_templates SET weekly_structure = '[
  {"week_number": 1, "focus": "Foundation", "sessions": [{"day": 2, "workout_name": "Aerobic Base Run (60 min)", "description": "Easy run", "duration_minutes": 60, "intensity": "easy"},{"day": 4, "workout_name": "Active Recovery Jog (40 min)", "description": "Recovery", "duration_minutes": 40, "intensity": "easy"},{"day": 6, "workout_name": "Aerobic Long Run HRR Z2 (90 min)", "description": "Long run", "duration_minutes": 90, "intensity": "easy"}]},
  {"week_number": 2, "focus": "Volume", "sessions": [{"day": 2, "workout_name": "Aerobic Base Run (60 min)", "description": "Base", "duration_minutes": 60, "intensity": "easy"},{"day": 4, "workout_name": "Aerobic Development Run (55 min, mid-Z2)", "description": "Development", "duration_minutes": 55, "intensity": "easy"},{"day": 6, "workout_name": "Aerobic Long Run HRR Z2 (90 min)", "description": "Long", "duration_minutes": 90, "intensity": "easy"}]},
  {"week_number": 3, "focus": "Build", "sessions": [{"day": 2, "workout_name": "Aerobic Run with Pickups (55 min)", "description": "Pickups", "duration_minutes": 55, "intensity": "moderate"},{"day": 4, "workout_name": "Active Recovery Jog (40 min)", "description": "Recovery", "duration_minutes": 40, "intensity": "easy"},{"day": 6, "workout_name": "Aerobic Zone 2 Run (75 min)", "description": "Long", "duration_minutes": 75, "intensity": "easy"}]},
  {"week_number": 4, "focus": "Recovery", "sessions": [{"day": 2, "workout_name": "Active Recovery Jog (40 min)", "description": "Easy", "duration_minutes": 40, "intensity": "easy"},{"day": 6, "workout_name": "Aerobic Base Run (60 min)", "description": "Light", "duration_minutes": 60, "intensity": "easy"}]},
  {"week_number": 5, "focus": "Progression", "sessions": [{"day": 2, "workout_name": "Aerobic Run With Strides (50 min)", "description": "Strides", "duration_minutes": 50, "intensity": "moderate"},{"day": 4, "workout_name": "Aerobic Development Run (55 min, mid-Z2)", "description": "Development", "duration_minutes": 55, "intensity": "easy"},{"day": 6, "workout_name": "Aerobic Long Run HRR Z2 (90 min)", "description": "Long", "duration_minutes": 90, "intensity": "easy"}]},
  {"week_number": 6, "focus": "Peak", "sessions": [{"day": 2, "workout_name": "Aerobic Run with Pickups (55 min)", "description": "Pickups", "duration_minutes": 55, "intensity": "moderate"},{"day": 4, "workout_name": "Aerobic Base Run (60 min)", "description": "Easy", "duration_minutes": 60, "intensity": "easy"},{"day": 6, "workout_name": "Aerobic Long Run HRR Z2 (90 min)", "description": "Long", "duration_minutes": 90, "intensity": "moderate"}]},
  {"week_number": 7, "focus": "Consolidation", "sessions": [{"day": 2, "workout_name": "Aerobic Run With Strides (50 min)", "description": "Strides", "duration_minutes": 50, "intensity": "moderate"},{"day": 4, "workout_name": "Active Recovery Jog (40 min)", "description": "Recovery", "duration_minutes": 40, "intensity": "easy"},{"day": 6, "workout_name": "Aerobic Zone 2 Run (75 min)", "description": "Long", "duration_minutes": 75, "intensity": "easy"}]},
  {"week_number": 8, "focus": "Test", "sessions": [{"day": 2, "workout_name": "Active Recovery Jog (40 min)", "description": "Taper", "duration_minutes": 40, "intensity": "easy"},{"day": 6, "workout_name": "Aerobic Base Run (60 min)", "description": "Assessment", "duration_minutes": 60, "intensity": "easy"}]}
]'::jsonb WHERE name IN ('Couch to 5K Base', 'Marathon Base Builder', 'Easy Running Foundation') AND discipline = 'running';

